-- ============================================================
-- Import batch KEDUA: 15 Sprin baru (21 Agustus - 5 September 2026) dari
-- C:\Database SPRIN SIandi\PART 2\ -- GATUR harian/mingguan, KRYD, Supervisi
-- Ops Libas Lodaya, SIAGA OPSNAL x2, UNRAS PT Namasindo, Pemberangkatan Massa
-- FPI, Dalmas, dan 3 Sprin PAM event (RW3 Fest, Bandung Ultra, Musik Forestra).
-- 1.702 baris penempatan personel (2 di antaranya ASN non-KUATPERS di Sprin
-- 1904), semua NRP tervalidasi terhadap roster pengguna (9 koreksi transkripsi
-- ditemukan & diperbaiki lewat pencocokan nama -- lihat laporan terpisah).
--
-- Tidak butuh jenis_kegiatan baru -- semua 15 Sprin cocok ke salah satu dari 4
-- jenis yang sudah ada: KEGIATAN RUTIN YANG DITINGKATKAN, PENGAMANAN UNJUK
-- RASA, PENGAMANAN KEGIATAN LAINNYA, OPERASI KEPOLISIAN KEWILAYAHAN.
--
-- Tidak idempoten sepenuhnya (sprin_kelompok/sprin_personel/personel_non_kuatpers
-- tidak dicek exists dulu) -- JANGAN dijalankan dua kali.
-- ============================================================

alter table public.surat_perintah disable trigger trg_surat_perintah_before_write;

insert into public.surat_perintah (
  nomor_agenda, nomor_lengkap, jenis_kegiatan_id, perihal, pertimbangan, lokasi,
  tanggal_mulai, tanggal_selesai, jam_apel, butir_untuk,
  status, disusun_oleh, disetujui_oleh, disetujui_pada
)
select
  x.nomor_agenda, x.nomor_lengkap, jk.id, x.perihal, x.pertimbangan, x.lokasi,
  x.tanggal_mulai::date, x.tanggal_selesai::date, nullif(x.jam_apel,'')::time,
  case when x.butir_untuk is null then null
    else array(select jsonb_array_elements_text(x.butir_untuk::jsonb)) end,
  'TERBIT'::status_surat_perintah,
  (select id from public.pengguna where nrp = '87121335'),
  (select id from public.pengguna where nrp = '76010326'),
  x.tanggal_mulai::date::timestamptz
from jsonb_to_recordset('[{"kode":"sprin1890","nomor_agenda":1890,"nomor_lengkap":"SPRIN/1890/VIII/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang Ditingkatkan (Patroli dan Razia Skala Besar) di Wilayah Hukum Polres Cimahi","pertimbangan":"bahwa dalam rangka Kegiatan Rutin yang ditingkatkan di Wilkum Polres Cimahi, maka dipandang perlu mengeluarkan surat perintah.","lokasi":"Wilkum Polres Cimahi","tanggal_mulai":"2026-08-22","tanggal_selesai":"2026-08-22","jam_apel":"21:00","butir_untuk":"[\"melaksanakan Kegiatan Rutin yang ditingkatkan / Patroli dan Razia Skala Besar dengan sasaran Pekat, Curat, Curas, Curanmor, Senpi, Sajam, Narkoba, Geng Motor dan orang mencurigakan / meresahkan disekitar Wilkum Polres Cimahi;\",\"apel kegiatan dilaksanakan pada hari Sabtu tanggal 22 Agustus 2026, Pukul 21.00 WIB di halaman Polres Cimahi dipimpin oleh KABAG OPS;\",\"pakaian PDL – II Two Tone memakai Rompi Hijau, Peluit, Borgol, Senter, untuk Sat Reserse, Sat Resnarkoba dan Sat Intelkam Menyesuaikan;\",\"melaksanakan perintah ini dengan saksama dan penuh rasa tanggung jawab;\",\"melaporkan hasil pelaksanaan tugas kepada Ka / Waka / Kabag Ops Polres Cimahi pada kesempatan pertama.\"]"},{"kode":"sprin1903","nomor_agenda":1903,"nomor_lengkap":"SPRIN/1903/VIII/PAM.3.3./2026","jenis_kegiatan_nama":"PENGAMANAN KEGIATAN LAINNYA","perihal":"Antisipasi kerawanan kamtibmas, penggelaran kekuatan dan pengaturan lalu lintas pagi dan sore di wilayah hukum Polres Cimahi pada hari Rabu tanggal 26 Agustus 2026","pertimbangan":"bahwa dalam rangka mendukung kepentingan dinas Kepolisian Resor Cimahi, maka dipandang perlu mengeluarkan surat perintah ini.","lokasi":"Wilkum Polres Cimahi","tanggal_mulai":"2026-08-26","tanggal_selesai":"2026-08-26","jam_apel":null,"butir_untuk":"[\"di samping tugas dan tanggung jawabnya ditunjuk untuk melaksanakan tugas antisipasi kerawanan kamtibmas, penggelaran kekuatan dan pengaturan lalu lintas pagi dan sore pa