insert into public.personel_non_kuatpers (nama, pangkat, nrp, jabatan_asal, keterangan, diinput_oleh)
select x.nama, x.pangkat, x.nrp, x.jabatan_asal, x.keterangan::keterangan_non_kuatpers,
  (select id from public.pengguna where nrp = '87121335')
from jsonb_to_recordset('[{"nrp":"197701292006042003","nama":"VRIETA SAFARINA, A.Md.","pangkat":"PENDA I","jabatan_asal":"SI DOKKES","keterangan":"LAINNYA"},{"nrp":"199105252022022000","nama":"HANI, A.Md.Keb.","pangkat":"PENGATUR","jabatan_asal":"SI DOKKES","keterangan":"LAINNYA"}]'::jsonb) as x(nrp text, nama text, pangkat text, jabatan_asal text, keterangan text)
where not exists (select 1 from public.personel_non_kuatpers where nrp = x.nrp);


