:"PAM AREA DAN PINTU MASUK"},{"nrp_aktif":"88010240","nonKuatpers":false,"nomor_urut_keseluruhan":60,"nomor_urut_kelompok":22,"jabatan_operasional":"PAM AREA DAN PINTU MASUK","nomor_lengkap":"SPRIN/1917/VIII/PAM.3.3./2026","kelompok_besar":null,"nama_kelompok":"PAM AREA DAN PINTU MASUK"}]'::jsonb) as x(
  nrp_aktif text, nomor_urut_keseluruhan int, nomor_urut_kelompok int, jabatan_operasional text,
  nomor_lengkap text, kelompok_besar text, nama_kelompok text
)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap
join public.sprin_kelompok sk
  on sk.surat_perintah_id = sp.id
  and sk.nama_kelompok = x.nama_kelompok
  and coalesce(sk.kelompok_besar,'') = coalesce(x.kelompok_besar,'')
join public.pengguna pg on pg.nrp = x.nrp_aktif;


insert into public.sprin_personel (sprin_kelompok_id, personel_non_kuatpers_id, nomor_urut_keseluruhan, nomor_urut_kelompok, jabatan_operasional)
select
  sk.id, nk.id, x.nomor_urut_keseluruhan, x.nomor_urut_kelompok, x.jabatan_operasional
from jsonb_to_recordset('[{"nrp_aktif":"197701292006042003","nonKuatpers":true,"nomor_urut_keseluruhan":41,"nomor_urut_kelompok":19,"jabatan_operasional":"GABUNGAN STAF","nomor_lengkap":"SPRIN/1904/VIII/PAM.3.2./2026","kelompok_besar":null,"nama_kelompok":"GABUNGAN STAF"},{"nrp_aktif":"199105252022022000","nonKuatpers":true,"nomor_urut_keseluruhan":42,"nomor_urut_kelompok":20,"jabatan_operasional":"GABUNGAN STAF","nomor_lengkap":"SPRIN/1904/VIII/PAM.3.2./2026","kelompok_besar":null,"nama_kelompok":"GABUNGAN STAF"}]'::jsonb) as x(
  nrp_aktif text, nomor_urut_keseluruhan int, nomor_urut_kelompok int, jabatan_operasional text,
  nomor_lengkap text, kelompok_besar text, nama_kelompok text
)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap
join public.sprin_kelompok sk
  on sk.surat_perintah_id = sp.id
  and sk.nama_kelompok = x.nama_kelompok
  and coalesce(sk.kelompok_besar,'') = coalesce(x.kelompok_besar,'')
join public.personel_non_kuatpers nk on nk.nrp = x.nrp_aktif;


